use xiom.io;
fn calc_bmi(weight_kg: Float64, height_m: Float64) -> Float64 {
  return weight_kg / (height_m * height_m);
}

fn bmi_category(bmi: Float64) -> Str {
  if bmi < 18.5 {
    return "Underweight";
  } elif bmi < 25.0 {
    return "Normal weight";
  } elif bmi < 30.0 {
    return "Overweight";
  } else {
    return "Obese";
  }
}

fn main() {
  let weight = 82.5;
  let height = 1.80;
  let bmi = calc_bmi(weight, height);
  let category = bmi_category(bmi);
  io.println("BMI calculation complete!");
}
